// Os parâmetros anotam-se: o compilador não tem de onde os deduzir
function saudar(nome: string, entusiasmo: number): string {
  return `Olá, ${nome}${"!".repeat(entusiasmo)}`;
}

console.log(saudar("Rita", 3)); // "Olá, Rita!!!"

// @ts-expect-error com noImplicitAny, um parâmetro sem anotação é erro
function saudarSolto(nome) {
  return `Olá, ${nome}`;
}

console.log(saudarSolto("Rita")); // "Olá, Rita"

// @ts-expect-error entusiasmo é number e não aceita texto
console.log(saudar("Rita", "muito"));

// Sem anotação de retorno: o engano passa despercebido na função
function precoComIva(base: number) {
  return (base * 1.23).toFixed(2); // toFixed devolve string, não number
}

const semAnotacao = precoComIva(100); // inferido: string
// @ts-expect-error o erro só aparece aqui, longe da causa
const dobro: number = semAnotacao * 2;
console.log(dobro);

// Com anotação de retorno: o compilador aponta para a linha errada
function precoComIvaFixo(base: number): number {
  // @ts-expect-error toFixed devolve string e a anotação apanha-o aqui
  return (base * 1.23).toFixed(2);
}

console.log(precoComIvaFixo(100));

// void: a função corre pelo efeito, não pelo valor
function registar(mensagem: string): void {
  console.log(`[log] ${mensagem}`);
}

registar("ficheiro gravado");

// @ts-expect-error o resultado de uma função void não se aproveita
const guardado: string = registar("nada");
console.log(guardado);

// A subtileza: num tipo de função, void significa "retorno ignorado"
const historico: string[] = [];
const aoGuardar: (m: string) => void = (m) => historico.push(m); // push devolve number
aoGuardar("primeiro");
console.log(historico.length); // 1

// Com undefined em vez de void, o mesmo já não passa
// @ts-expect-error number não é atribuível a undefined
const aoGuardarEstrito: (m: string) => undefined = (m) => historico.push(m);
console.log(aoGuardarEstrito);

// never: a função nunca chega a devolver
function falhar(mensagem: string): never {
  throw new Error(mensagem);
}

function cicloEterno(): never {
  while (true) {
    // um processo de eventos que nunca termina
  }
}

// O compilador sabe que depois de falhar() não há continuação
function lerPorto(valor: string | null): string {
  if (valor === null) {
    falhar("PORT em falta");
  }
  return valor; // aqui valor já é string
}

console.log(lerPorto("8080")); // "8080"
console.log(typeof cicloEterno); // "function"

// @ts-expect-error uma função que termina normalmente não pode devolver never
function terminaSempre(): never {
  console.log("acabei");
}
console.log(terminaSempre);

// Retorno inferido: o tipo do objeto sai do literal devolvido
function criarBilhete(evento: string, lugar: number) {
  return { evento, lugar, emitido: new Date(), usado: false };
}
// inferido: { evento: string; lugar: number; emitido: Date; usado: boolean }
const bilhete = criarBilhete("Concerto", 14);
console.log(bilhete.usado); // false

// Retorno anotado: a interface fixa o contrato
interface Bilhete {
  evento: string;
  lugar: number;
}

function emitirBilhete(evento: string, lugar: number): Bilhete {
  // @ts-expect-error a anotação recusa propriedades a mais no literal devolvido
  return { evento, lugar, usado: false };
}

console.log(emitirBilhete("Teatro", 3).lugar); // 3

// Numa arrow function o retorno anota-se antes da seta
const duplicar = (n: number): number => n * 2;

// Com corpo em chavetas é exatamente o mesmo sítio
const iniciais = (nome: string): string => {
  return nome
    .split(" ")
    .map((p) => p[0])
    .join("");
};

// Devolver um objeto literal obriga a parênteses à volta das chavetas
const criarPonto = (x: number, y: number): { x: number; y: number } => ({ x, y });

console.log(duplicar(21)); // 42
console.log(iniciais("Ana Maria Costa")); // "AMC"
console.log(criarPonto(1, 2).y); // 2

const precos = [10, 20, 30];

// p vem tipado do contexto: map sabe que o array é number[]
const comIva = precos.map((p) => Math.round(p * 1.23));
const caros = precos.filter((p) => p > 15);

console.log(comIva); // [12, 25, 37]
console.log(caros); // [20, 30]

// Anotar à mão compila, mas só acrescenta ruído e mais um sítio para atualizar
const ruidoso = precos.map((p: number): number => Math.round(p * 1.23));
console.log(ruidoso.length); // 3

// Fora de um contexto que o tipe, o parâmetro volta a precisar de anotação
// @ts-expect-error não há contexto de onde deduzir o tipo de p
const solto = (p) => p * 1.23;
console.log(solto);

