function aplicarDesconto(preco: number, percentagem: number): number {
  return preco - (preco * percentagem) / 100;
}

function formatarPreco(valor: number, moeda: string): string {
  return `${valor.toFixed(2)} ${moeda}`;
}

const precoFinal = (preco: number, percentagem: number): string =>
  formatarPreco(aplicarDesconto(preco, percentagem), "EUR");

console.log(aplicarDesconto(100, 25)); // 75
console.log(formatarPreco(75, "EUR")); // "75.00 EUR"
console.log(precoFinal(100, 25)); // "75.00 EUR"

// @ts-expect-error percentagem é number e não aceita texto
console.log(aplicarDesconto(100, "25"));

const enviadas: string[] = [];

function notificar(canal: string, mensagem: string): void {
  enviadas.push(`${canal}: ${mensagem}`);
}

// void num tipo de função significa "o retorno é ignorado":
// esta arrow devolve number (o push) e mesmo assim encaixa
const aoNotificar: (mensagem: string) => void = (mensagem) =>
  enviadas.push(mensagem);

notificar("email", "encomenda enviada");
aoNotificar("direto");

console.log(enviadas.length); // 2

// @ts-expect-error notificar devolve void: não há valor para guardar
const recibo: string = notificar("sms", "ok");
console.log(recibo);

interface Encomenda {
  referencia: string;
  total: number;
  estado: string;
}

// Retorno anotado: o contrato fica preso à interface
function criarEncomenda(referencia: string, total: number): Encomenda {
  return { referencia, total, estado: "pendente" };
}

// Retorno inferido: repare que o tipo inclui a propriedade extra
function criarEncomendaSolta(referencia: string, total: number) {
  return { referencia, total, estado: "pendente", interno: true };
}
// inferido: { referencia: string; total: number; estado: string; interno: boolean }

const oficial = criarEncomenda("A-1", 49.9);
const solta = criarEncomendaSolta("A-2", 10);

console.log(oficial.estado); // "pendente"
console.log(solta.interno); // true

// @ts-expect-error interno não pertence a Encomenda
console.log(oficial.interno);

function criarComExtra(referencia: string, total: number): Encomenda {
  // @ts-expect-error a anotação recusa a propriedade a mais no literal devolvido
  return { referencia, total, estado: "pendente", interno: true };
}
console.log(criarComExtra("A-3", 5).total); // 5

interface Definicoes {
  porto: number;
  host: string;
}

// Nunca devolve: lança sempre
function emFalta(chave: string): never {
  throw new Error(`Definição obrigatória em falta: ${chave}`);
}

// Nunca devolve: nunca termina
function aguardarParaSempre(): never {
  while (true) {
    // fica à espera de sinais do sistema
  }
}

// Como emFalta devolve never, o compilador sabe que a linha seguinte
// só corre quando o valor existe, e estreita o tipo sozinho
function lerDefinicoes(
  cru: Record<string, string | undefined>,
): Definicoes {
  const porto = cru["PORTO"];
  if (porto === undefined) {
    emFalta("PORTO");
  }
  const host = cru["HOST"];
  if (host === undefined) {
    emFalta("HOST");
  }
  return { porto: Number(porto), host }; // porto e host já são string
}

const registarArranque = (d: Definicoes): void => {
  console.log(`a servir em ${d.host}:${d.porto}`);
};

const definicoes = lerDefinicoes({ PORTO: "8080", HOST: "localhost" });
registarArranque(definicoes); // "a servir em localhost:8080"
console.log(typeof aguardarParaSempre); // "function"

// @ts-expect-error uma função que chega ao fim não pode ser anotada never
function quaseNever(): never {
  console.log("cheguei ao fim");
}
console.log(quaseNever);
